'use client';
import { useState, useEffect, useMemo } from 'react';
import axios from 'axios';
import { 
  Edit as EditIcon, 
  Delete as DeleteIcon, 
  Save as SaveIcon,
  Group as GroupIcon,
  Person as PersonIcon,
  Search as SearchIcon,
  Clear as ClearIcon,
  ArrowBack as ArrowBackIcon
} from '@mui/icons-material';
import Layout from "../components/Layout";
import { useRouter } from 'next/navigation';

export default function EditGroupe({ params }) {
  const { id } = params;
  const router = useRouter();
  const [groupe, setGroupe] = useState(null);
  const [etudiants, setEtudiants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);

  // Fetch group and students data
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const [groupeResponse, etudiantsResponse] = await Promise.all([
          axios.get(`http://localhost:5000/api/groupes/${id}`),
          axios.get('http://localhost:5000/api/etudiants')
        ]);

        setGroupe(groupeResponse.data);
        
        // Process students data
        const etudiantsWithGroupInfo = etudiantsResponse.data.map(e => ({
          ...e,
          inCurrentGroup: e.idGroupe === parseInt(id)
        }));
        
        setEtudiants(etudiantsWithGroupInfo);
      } catch (err) {
        console.error("Error fetching data:", err);
        setError("Failed to load group data");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [id]);

  // Filter students based on search term
  const filteredEtudiants = useMemo(() => {
    if (!searchTerm.trim()) return etudiants;
    return etudiants.filter(e => 
      `${e.nom} ${e.prenom}`.toLowerCase().includes(searchTerm.toLowerCase()) ||
      `${e.prenom} ${e.nom}`.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [etudiants, searchTerm]);

  // Handle adding/removing students from group
  const toggleStudentInGroup = async (etudiant) => {
    try {
      setSaving(true);
      
      if (etudiant.inCurrentGroup) {
        // Remove from group
        await axios.put(`http://localhost:5000/api/etudiants/${etudiant.idEtudiant}`, {
          idGroupe: null
        });
      } else {
        // Add to group
        await axios.put(`http://localhost:5000/api/etudiants/${etudiant.idEtudiant}`, {
          idGroupe: id
        });
      }

      // Update local state
      setEtudiants(prev => prev.map(e => 
        e.idEtudiant === etudiant.idEtudiant 
          ? { ...e, inCurrentGroup: !e.inCurrentGroup } 
          : e
      ));
      
      // Also update group's student list if we have it
      if (groupe?.etudiants) {
        if (etudiant.inCurrentGroup) {
          setGroupe(prev => ({
            ...prev,
            etudiants: prev.etudiants.filter(e => e.idEtudiant !== etudiant.idEtudiant)
          }));
        } else {
          setGroupe(prev => ({
            ...prev,
            etudiants: [...prev.etudiants, etudiant]
          }));
        }
      }
    } catch (err) {
      console.error("Error updating student:", err);
      setError("Failed to update student");
    } finally {
      setSaving(false);
    }
  };

  // Handle group deletion
  const handleDeleteGroup = async () => {
    if (!window.confirm("Are you sure you want to delete this group? All students will be unassigned.")) return;
    
    try {
      await axios.delete(`http://localhost:5000/api/groupes/${id}`);
      router.push('/gestion-groupes');
    } catch (err) {
      console.error("Error deleting group:", err);
      setError("Failed to delete group");
    }
  };

  if (loading) {
    return (
      <Layout title="Edit Group">
        <div className="flex justify-center items-center h-64">
          <p className="text-lg">Loading group data...</p>
        </div>
      </Layout>
    );
  }

  if (!groupe) {
    return (
      <Layout title="Group Not Found">
        <div className="flex justify-center items-center h-64">
          <p className="text-lg">Group not found</p>
        </div>
      </Layout>
    );
  }

  return (
    <Layout title={`Edit Group: ${groupe.nomGroupe}`}>
      <div className="p-4 max-w-7xl mx-auto">
        {/* Back button and group info */}
        <div className="flex items-center mb-6">
          <button 
            onClick={() => router.push('/gestion-groupes')}
            className="mr-4 p-2 rounded-full hover:bg-gray-100"
          >
            <ArrowBackIcon />
          </button>
          <div>
            <h1 className="text-2xl font-bold">{groupe.nomGroupe}</h1>
            <p className="text-gray-600">
              {groupe.etudiants?.length || 0} member(s)
            </p>
          </div>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-red-100 text-red-700 rounded">
            {error}
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Current group members */}
          <div className="bg-white rounded-lg shadow p-4">
            <h2 className="text-xl font-semibold mb-4 flex items-center">
              <GroupIcon className="mr-2" /> Group Members
            </h2>
            
            {groupe.etudiants?.length > 0 ? (
              <ul className="divide-y divide-gray-200">
                {groupe.etudiants.map(etudiant => (
                  <li key={etudiant.idEtudiant} className="py-3 flex justify-between items-center">
                    <div className="flex items-center">
                      <PersonIcon className="text-gray-400 mr-2" />
                      <span>{etudiant.nom} {etudiant.prenom}</span>
                    </div>
                    <button
                      onClick={() => toggleStudentInGroup(etudiant)}
                      disabled={saving}
                      className="px-3 py-1 bg-red-100 text-red-600 rounded hover:bg-red-200 disabled:opacity-50"
                    >
                      Remove
                    </button>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-gray-500 italic">No students in this group</p>
            )}

            <div className="mt-4">
              <button
                onClick={handleDeleteGroup}
                className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 flex items-center"
              >
                <DeleteIcon className="mr-2" /> Delete Group
              </button>
            </div>
          </div>

          {/* Available students */}
          <div className="bg-white rounded-lg shadow p-4">
            <h2 className="text-xl font-semibold mb-4 flex items-center">
              <PersonIcon className="mr-2" /> Available Students
            </h2>
            
            <div className="mb-4 relative">
              <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                <SearchIcon className="text-gray-400" />
              </div>
              <input
                type="text"
                placeholder="Search students..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 p-2 border rounded focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
              {searchTerm && (
                <button
                  onClick={() => setSearchTerm('')}
                  className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                >
                  <ClearIcon />
                </button>
              )}
            </div>

            <div className="overflow-y-auto max-h-96">
              {filteredEtudiants.filter(e => !e.inCurrentGroup).length > 0 ? (
                <ul className="divide-y divide-gray-200">
                  {filteredEtudiants
                    .filter(e => !e.inCurrentGroup)
                    .map(etudiant => (
                      <li 
                        key={etudiant.idEtudiant} 
                        className="py-3 flex justify-between items-center hover:bg-gray-50"
                      >
                        <div className="flex items-center">
                          <PersonIcon className="text-gray-400 mr-2" />
                          <span>{etudiant.nom} {etudiant.prenom}</span>
                        </div>
                        <button
                          onClick={() => toggleStudentInGroup(etudiant)}
                          disabled={saving}
                          className="px-3 py-1 bg-blue-100 text-blue-600 rounded hover:bg-blue-200 disabled:opacity-50"
                        >
                          Add to Group
                        </button>
                      </li>
                    ))}
                </ul>
              ) : (
                <p className="text-gray-500 italic">
                  {searchTerm ? "No matching students found" : "No available students"}
                </p>
              )}
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
}